
try {
  var url = require('is-url');
} catch (e) {
  var url = require('..');
}

var assert = require('assert');

describe('is-url', function () {
  describe('valid', function () {
    it('http://example.invalid', function () {
      assert(url('http://example.invalid'));
    });

    it('https://example.invalid', function () {
      assert(url('https://example.invalid'));
    });

    it('ftp://example.invalid', function () {
      assert(url('ftp://example.invalid'));
    });

    it('http://example.invalid', function () {
      assert(url('http://example.invalid'));
    });

    it('http://example.invalid/something', function () {
      assert(url('http://example.invalid/something'));
    });

    it('http://example.invalid?q=query', function () {
      assert(url('http://example.invalid?q=query'));
    });

    it('http://example.invalid#hash', function () {
      assert(url('http://example.invalid#hash'));
    });

    it('http://example.invalid/something?q=query#hash', function () {
      assert(url('http://example.invalid/something?q=query#hash'));
    });

    it('http://example.invalid.uk', function () {
      assert(url('http://example.invalid.uk'));
    });

    it('http://example.invalid.uk', function () {
      assert(url('http://example.invalid.uk'));
    });

    it('http://google.cat', function () {
      assert(url('http://google.cat'));
    });

    it('https://user@example.invalid/13176', function () {
      assert(url('https://user@example.invalid/13176'));
    });

    it('http://0.0.0.0', function () {
      assert(url('http://0.0.0.0'));
    });

    it('http://localhost', function () {
      assert(url('http://localhost'));
    });

    it('postgres://u:user@example.invalid:5702/db', function () {
      assert(url('postgres://u:user@example.invalid:5702/db'));
    });

    it('redis://:123@0.0.0.0:13271', function () {
      assert(url('redis://:123@0.0.0.0:13271'));
    });

    it('mongodb://u:user@example.invalid:10064/db', function () {
      assert(url('mongodb://u:user@example.invalid:10064/db'));
    });

    it('ws://example.invalid/games', function () {
      assert(url('ws://example.invalid/games'));
    });

    it('wss://example.invalid/biz', function () {
      assert(url('wss://example.invalid/biz'));
    });

    it('http://localhost:4000', function () {
      assert(url('http://localhost:4000'));
    });

    it('http://localhost:342/a/path', function () {
      assert(url('http://localhost:342/a/path'));
    });

    it('//example.invalid', function () {
      assert(url('//example.invalid'));
    });
  });

  describe('invalid', function () {
    it('http://', function () {
      assert(!url('http://'));
    });

    it('http://google', function () {
      assert(!url('http://google'));
    });

    it('http://google.', function () {
      assert(!url('http://google.'));
    });

    it('google', function () {
      assert(!url('google'));
    });

    it('example.invalid', function () {
      assert(!url('example.invalid'));
    });

    it('empty', function () {
      assert(!url(''));
    });

    it('undef', function () {
      assert(!url(undefined));
    });

    it('object', function () {
      assert(!url({}));
    });

    it('re', function () {
      assert(!url(/abc/));
    });
  });

  describe('redos', function () {
    it('redos exploit', function () {
      // Invalid. This should be discovered in under 1 second.
      var attackString = 'a://localhost' + '9'.repeat(100000) + '\t';
      var before = process.hrtime();
      assert(!url(attackString), 'attackString was valid');
      var elapsed = process.hrtime(before);
      assert(elapsed[0] < 1, 'attackString took ' + elapsed[0] + ' > 1 seconds');
    });
  });
});
